-- v1.85.0: email template settings per theme.
-- Every outgoing email wraps its body in a branded shell (top + bottom bar
-- with tenant-selected colors, ImpactIQ mark on the left of the header,
-- tenant logo on the right, "Generated by ImpactIQ · <date>" on the right
-- of the footer). Storing on app_themes keeps it in lockstep with the rest
-- of the theme so switching themes swaps email look too.
ALTER TABLE app_themes
  ADD COLUMN IF NOT EXISTS email_top_bar_color text,
  ADD COLUMN IF NOT EXISTS email_bottom_bar_color text,
  ADD COLUMN IF NOT EXISTS email_footer_left_text text,
  -- 'light' | 'dark' — which of the two uploaded logos to embed in the
  -- header's right side. Falls back to logoLight when null.
  ADD COLUMN IF NOT EXISTS email_header_logo_variant text;
